using System.Collections.Generic;

namespace KeyQuest.Academy.Native
{
    public sealed class LessonExercise
    {
        public string Title { get; private set; }
        public string Target { get; private set; }
        public string Instruction { get; private set; }

        public LessonExercise(string title, string target, string instruction)
        {
            Title = title;
            Target = target;
            Instruction = instruction;
        }
    }

    public sealed class TypingLesson
    {
        public string Id { get; private set; }
        public string Title { get; private set; }
        public string Level { get; private set; }
        public string Description { get; private set; }
        public int EstimatedMinutes { get; private set; }
        public IList<LessonExercise> Exercises { get; private set; }

        public TypingLesson(string id, string title, string level, string description, int estimatedMinutes, IList<LessonExercise> exercises)
        {
            Id = id; Title = title; Level = level; Description = description;
            EstimatedMinutes = estimatedMinutes; Exercises = exercises;
        }
    }

